'use strict';

// MODULES //

import numelDimension from '@stdlib/ndarray-base-numel-dimension';
import getStride from '@stdlib/ndarray-base-stride';
import getOffset from '@stdlib/ndarray-base-offset';
import getData from '@stdlib/ndarray-base-data-buffer';
import { ndarray as strided } from '@stdlib/blas-ext-base-slast-index-of-truthy';


// MAIN //

/**
* Returns the index of the last truthy element in a one-dimensional single-precision floating-point ndarray.
*
* ## Notes
*
* -   The function expects the following ndarrays:
*
*     -   a one-dimensional input ndarray.
*
* @param {ArrayLikeObject<Object>} arrays - array-like object containing ndarrays
* @returns {integer} index
*
* @example
* import Float32Vector from '@stdlib/ndarray-vector-float32';
*
* var x = new Float32Vector( [ 0.0, 1.0, 0.0, 2.0 ] );
*
* var v = slastIndexOfTruthy( [ x ] );
* // returns 3
*/
function slastIndexOfTruthy( arrays ) {
	var x = arrays[ 0 ];
	return strided( numelDimension( x, 0 ), getData( x ), getStride( x, 0 ), getOffset( x ) );
}


// EXPORTS //

export default slastIndexOfTruthy;
